"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
import os
from pathlib import Path
import re
import sys


PERIOD = re.compile(r"([1-9][0-9]*)([rsmhd])")
CODE = re.compile(r"[+-]?[0-9]+")
SECONDS = {"s": 1, "m": 60, "h": 3600, "d": 86400}


def reject_constant(value):
    raise ValueError("non-JSON constant: " + value)


def read_table(node, name, bad):
    path = node / "wf" / (name + ".json")
    try:
        # Avoid updating access time where the filesystem supports O_NOATIME.
        try:
            fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOATIME", 0))
        except PermissionError:
            fd = os.open(path, os.O_RDONLY)
        with os.fdopen(fd, encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError):
        data = None
    if (not isinstance(data, dict) or data.get("contract") != "wf-table/1"
            or not isinstance(data.get("columns"), list)
            or not all(isinstance(item, str) for item in data["columns"])
            or not isinstance(data.get("rows"), list)):
        bad.append({"table": name, "row": None, "why": "bad_table"})
        return []
    return data["rows"]


def timestamp(value, now):
    result = datetime.fromisoformat(value)
    return result.replace(tzinfo=now.tzinfo) if result.tzinfo is None else result


def routine(row, now):
    period = PERIOD.fullmatch(row["every"])
    if period is None:
        raise ValueError("invalid every")
    last = row["last_time"]
    time = timestamp(last, now) if last else None
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = raw_code
    elif CODE.fullmatch(raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid last_code")
    next_time = None
    if time is not None and period.group(2) != "r":
        duration = int(period.group(1)) * SECONDS[period.group(2)]
        next_time = time + timedelta(seconds=duration)
    if code == "running":
        state = "running"
    elif time is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif next_time is not None and now >= next_time:
        state = "overdue"
    else:
        state = "ok"
    rendered = (next_time.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                if next_time is not None else None)
    return {"name": row["name"], "every": row["every"],
            "last_time": last or None, "last_code": code,
            "state": state, "next": rendered}


def appointment(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    bad = []
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": dict.fromkeys(
                  ("running", "never", "failed", "overdue", "ok"), 0),
                  "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)},
              "bad": bad}
    for table in ("routines", "schedule"):
        seen = set()
        required = (("name", "every", "last_time", "last_code") if table == "routines"
                    else ("name", "at", "claimed"))
        for index, row in enumerate(read_table(node, table, bad)):
            why = None
            if not isinstance(row, dict):
                why = "bad_row"
            else:
                name = row.get("name")
                if isinstance(name, str) and name:
                    if name in seen:
                        why = "dup_name"
                    seen.add(name)
                if why is None and (not isinstance(name, str) or not name
                                    or not all(key in row for key in required)
                                    or not all(isinstance(value, str) for value in row.values())):
                    why = "bad_row"
            if why is None:
                try:
                    item = routine(row, now) if table == "routines" else appointment(row, now)
                except (ValueError, OverflowError):
                    why = "bad_row"
            if why is not None:
                bad.append({"table": table, "row": index, "why": why})
            else:
                result[table].append(item)
                result["counts"][table][item["state"]] += 1
        result[table].sort(key=lambda item: item["name"])
    bad.sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow runs summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
